def desde_claves(textos):
    falta = set(CLAVES) - set(textos)
    if falta:
        raise SystemExit("[error] faltan claves de mercado: " + ", ".join(sorted(falta)))
    return [(CLAVES[k], textos[k]) for k in CLAVES]
